"use strict";(self.webpackChunkcoursesmith_site=self.webpackChunkcoursesmith_site||[]).push([["536"],{5495(e,t,o){o.r(t),o.d(t,{metadata:()=>a,default:()=>p,frontMatter:()=>r,contentTitle:()=>c,toc:()=>l,assets:()=>h});var a=JSON.parse('{"id":"m19-capstone-rollout/quiz","title":"Quiz: Capstone","description":"<Quiz questions={[","source":"@site/docs/m19-capstone-rollout/quiz.mdx","sourceDirName":"m19-capstone-rollout","slug":"/m19-capstone-rollout/quiz","permalink":"/306-agentic-devops-claude/docs/m19-capstone-rollout/quiz","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":3,"frontMatter":{"sidebar_position":3,"title":"Quiz: Capstone"},"sidebar":"courseSidebar","previous":{"title":"Lab: Capstone Incident","permalink":"/306-agentic-devops-claude/docs/m19-capstone-rollout/lab"},"next":{"title":"Deep Dive (Part 2)","permalink":"/306-agentic-devops-claude/docs/m19-capstone-rollout/deep-dive"}}'),n=o(4848),i=o(8453),s=o(7517);let r={sidebar_position:3,title:"Quiz: Capstone"},c="Capstone: Campaign Incident, Packaging & Rollout \u2014 Quiz",h={},l=[];function d(e){let t={h1:"h1",header:"header",...(0,i.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.header,{children:(0,n.jsx)(t.h1,{id:"capstone-campaign-incident-packaging--rollout--quiz",children:"Capstone: Campaign Incident, Packaging & Rollout \u2014 Quiz"})}),"\n",(0,n.jsx)(s.A,{questions:[{prompt:"INC-006 fires five failures at once. The retry storm is the loudest, so an engineer restarts orders-api, the metric recovers, and they close the ticket. Why does the 14-step workflow put Triage-lock as step 1, before any investigation?",options:[{text:"The lock claims the incident for exactly one loop and anchors the work on the whole incident",correct:!0,explanation:"Correct. Keyed by the correlation id, one holder wins and every concurrent contender is rejected, so a routine and a webhook both waking on INC-006 cannot open two remediations. And anchoring on the locked incident rather than an alert carries you through all five tracks instead of just the loudest."},{text:"The lock is a formality that satisfies the audit log; the real work is the loudest alert",correct:!1,explanation:"The lock is the concurrency guard that stops two loops racing on one incident, not paperwork. And 'fix the loudest alert first' is precisely the failure the capstone tests against \u2014 a compound incident handled one loud signal at a time drops the quieter tracks."},{text:"Locking first makes the investigation faster because it caches the collected evidence",correct:!1,explanation:"The lock does not cache evidence or speed anything up. It is about ownership and ordering: guarantee a single owner and anchor the workflow on the whole incident, not make any step run quicker."},{text:"The order does not matter at all \u2014 the fourteen steps are independent tasks that run in any sequence you like",correct:!1,explanation:"The order is the point. Each gate is a precondition for the next phase: you cannot reconcile hypotheses you never formed, review a repair never proposed, or verify a canary for a deploy that skipped the gate."}]},{prompt:"The novice failure mode on INC-006 is to grab the loudest alert and start fixing. What does the capstone actually test that this failure mode fails?",options:[{text:"Handling all five tracks without dropping any, not producing a right outcome on one",correct:!0,explanation:"Correct. Restarting orders-api fixes one track while leaving the dangerous plan un-reviewed, the missing limits in place, and the stale runbook to mislead the next on-call. A right outcome on one track is not success when four others were never touched \u2014 the discipline is coverage of the whole compound incident."},{text:"Fixing the single most severe failure as quickly as possible under time pressure",correct:!1,explanation:"Speed on the loudest failure is exactly the novice move. The exam is not who fixes one track fastest; it is whether you run the right procedure on each of the five tracks without letting one emergency make you forget another."},{text:"Choosing the correct model and effort level for the loudest track's specialist",correct:!1,explanation:"Model and effort tuning is not what the compound incident tests. The point is track coverage and correct sequencing across all five failures, not optimizing the configuration of a single specialist."},{text:"Writing the most detailed and thorough post-incident report for the single track that ended up being fixed",correct:!1,explanation:"A thorough report on one fixed track still leaves four tracks unaddressed. The capstone tests whether every track was handled through the workflow, not the polish of the write-up on the one you happened to fix."}]},{prompt:"In Phase 2, three tracks investigate INC-006 in parallel and all report the same root cause. The reconcile step calls this 'corroborated' rather than averaging the three. What must be true for agreement to count as real corroboration?",options:[{text:"Each track reached its conclusion from its OWN evidence, not by anchoring on a peer",correct:!0,explanation:"Correct. Independence is the precondition. Three independent lines of evidence converging is a real signal; three agents echoing one guess is one guess in three hats. The synthesizer rejects a packet whose conclusion is derived from another agent instead of its own sources."},{text:"The three tracks used the same model and effort level so the answers are comparable",correct:!1,explanation:"Same model and effort make the tracks MORE likely to anchor identically, not more trustworthy. Corroboration is about independent evidence, not matched configuration \u2014 differently-scoped specialists reaching one cause from different evidence is stronger."},{text:"A majority \u2014 two of the three tracks agreeing \u2014 is enough to declare the cause",correct:!1,explanation:"Corroboration is not a vote count. Two tracks that both anchored on the first are not two confirmations but zero. And a genuine split is surfaced as signal about missing evidence, not out-voted or averaged away."},{text:"The tracks ran sequentially so each could check the previous one's work",correct:!1,explanation:"Running them sequentially is how you MANUFACTURE consensus theater \u2014 every later track anchors on the earlier ones. The value of fanning out is independent reasoning; letting each track see the others destroys it."}]},{prompt:"During INC-006 the sre-investigator wants to apply a quick config fix and the change-reviewer wants to edit the runbook it flagged. The role-authority check refuses both (exit 3) but lets the iac-engineer write (exit 0). What principle is this enforcing?",options:[{text:"Authority is scoped per role by tool bundle \u2014 read-only roles have no write tool at all",correct:!0,explanation:"Correct. The investigator may query but not edit; the reviewer may inspect but not modify (independence requires it cannot touch what it judges); the iac-engineer may write because authoring HCL is its job. Scoped authority is what makes 'the right specialist, in-authority' a checkable fact."},{text:"Only the most senior role, iac-engineer, is trusted to write; the others are junior",correct:!1,explanation:"It is not a seniority ranking. The change-reviewer runs on the strongest model and is anything but junior \u2014 it is read-only precisely because a reviewer that can edit what it reviews loses independence. Write authority follows the role's job, not a trust tier."},{text:"The investigator and reviewer are blocked only because production is the target",correct:!1,explanation:"The refusal is structural, not environment-conditional: those roles have no write tool in their bundle, so they cannot write anywhere. Environment rules are a separate layer and do not grant a read-only role write access on staging."},{text:"The check is advisory \u2014 the blocked roles could still write if they chose to override it",correct:!1,explanation:"It is not advisory. A role with no write tool cannot grant itself the ability by ignoring a check; the capability is simply absent. That is the difference between a policy an agent can argue with and a boundary it structurally cannot cross."}]},{prompt:"The capstone review pipeline BLOCKS the prod Terraform plan because it opens a 0.0.0.0/0 security group. A teammate says 'the campaign launches in two hours \u2014 just apply it and tighten the rule afterward.' Why does the workflow refuse a direct apply?",options:[{text:"Repairs go proposal \u2192 review \u2192 gate, never direct apply \u2014 fix the plan and re-run the chain",correct:!0,explanation:"Correct. The design assumes pressure will tempt a shortcut, so the deny is structural: the PreToolUse gate blocks prod apply and one dissent in the review chain stops the line. Opening 0.0.0.0/0 during a high-traffic launch is when it is most dangerous. You correct the plan and send it back through, not around."},{text:"A direct apply is perfectly fine here as long as you remember to open a follow-up ticket to tighten the rule afterward",correct:!1,explanation:"A follow-up ticket does not un-expose the security group in the window between apply and fix \u2014 during a launch, that window is the worst possible time to be open to the world. The gate blocks the apply so 'fix it later' cannot put an exposure into production."},{text:"The block is a false positive; 0.0.0.0/0 on a security group is normal for public services",correct:!1,explanation:"A public load balancer terminates public traffic; a database or internal security group open to 0.0.0.0/0 is an exposure, and that is what the plan proposed. The security stage flags it as a reasoned objection, not a coin flip."},{text:"You should disable the change gate for two hours so the launch is not blocked",correct:!1,explanation:"Disabling the gate to push a change through is itself the rollback trigger on the adoption ladder \u2014 the exact action that says the operating layer can no longer be trusted at its level. The gate exists to hold under pressure; switching it off defeats its only purpose."}]},{prompt:"You are packaging the operating layer as a reusable starter plugin. Which of these belong IN the versioned starter? (Select all that belong in the reusable starter.)",multiSelect:!0,options:[{text:"The seven role agents \u2014 they encode authority boundaries, not Northstar business logic",correct:!0,explanation:"Correct. The agents are the governance layer: read-only investigator, scoped writers, independent reviewer. Their value is the authority structure, which ports to any repo. They belong in the starter."},{text:"The change gate hook and the authority, environment, and change contracts",correct:!0,explanation:"Correct. The gate's deny rules (no prod apply, no protected-namespace delete, no wildcard blast radius) and the contract schemas are policy, not data. They are exactly what a new team needs and exactly what should be versioned."},{text:"The INC-006 incident ticket and the fault fixtures Northstar injected",correct:!1,explanation:"These stay project-specific. The incidents and fixtures describe Northstar's systems; another team has its own. Shipping them would make the starter a copy of one repo rather than a portable layer."},{text:"The retry-storm answer key \u2014 the graded rubric tuned to Northstar's INC-002",correct:!1,explanation:"The answer key is graded against Northstar's specific incident, so it stays project-specific. The eval-score MECHANISM is reusable and ships; the KEY it scores against is per-project data each team writes for its own incidents."}]},{prompt:"The adoption ladder runs read-only pilot \u2192 PR proposals \u2192 approval-gated changes \u2192 bounded closed loop. Why does it start read-only and refuse to skip levels?",options:[{text:"Authority only widens after evidence at the current level shows widening is safe",correct:!0,explanation:"Correct. Trust is earned, not granted: you verify the agent diagnoses well before it can ever write, prove PRs are safe before granting apply, and so on. Each level produces the evidence that justifies the next, and every level is reversible via its rollback trigger."},{text:"The ladder starts read-only only to satisfy compliance; a capable agent can go straight to closed-loop",correct:!1,explanation:"Skipping to closed-loop grants write and apply authority with no evidence the agent diagnoses correctly or that its PRs are safe. The ladder is not a compliance ritual \u2014 placing an unproven agent at the top level is exactly the risk it exists to prevent."},{text:"The levels are ordered by how much CI time each stage consumes, cheapest first",correct:!1,explanation:"The ordering is by earned authority, not CI cost. Read-only is first because it verifies diagnosis quality before any write is possible, not because it is the cheapest stage to run."},{text:"You skip levels whenever the agent scores well once, because one good run proves reliability",correct:!1,explanation:"A single good run is one favourable draw, not proof \u2014 the same lesson M18 taught with replay distributions. Graduation requires sustained evidence (ten clean diagnoses, twenty merged PRs), not one score, because agents are nondeterministic."}]},{prompt:"The top level of the adoption ladder is described as a 'bounded' closed loop rather than full autonomy. What makes it bounded?",options:[{text:"The agent acts only within fail-closed guardrails it cannot disable, with a human audit after",correct:!0,explanation:"Correct. A closed loop can run continuously, but 'bounded' means every action stays inside guardrails that are fail-closed checks the agent cannot switch off, and a human audits post-hoc. That is the difference from handing over the keys \u2014 a scope boundary, not a free hand."},{text:"The agent runs on a fixed schedule rather than continuously",correct:!1,explanation:"'Bounded' refers to the guardrails on what the agent may DO, not to timing. A closed loop can run continuously; what bounds it is that every action stays inside fail-closed limits it cannot disable, with human audit afterward."},{text:"The agent is limited to a maximum number of actions per incident before stopping",correct:!1,explanation:"An action count is not what bounds it. The boundary is the fail-closed guardrails the agent cannot disable plus post-hoc human audit \u2014 a scope limit on what it may do, not a quota on how many things it does."},{text:"The agent must pause and ask a human to explicitly approve each individual action before that action is allowed to take effect",correct:!1,explanation:"Per-action approval is the approval-gated level below, not the bounded closed loop. At the top level the agent acts within guardrails and a human audits AFTERWARD; requiring live approval for each action would make it not a closed loop at all."}]},{prompt:"The lesson says 'evidence before hypothesis' (steps 2\u20133): you collect structured multi-source evidence, then form hypotheses \u2014 not the other way round. Why does this ordering matter?",options:[{text:"A hypothesis formed first anchors the search, so evidence gets cherry-picked to fit it",correct:!0,explanation:"Correct. Leading with a hypothesis turns investigation into confirmation \u2014 you gather what supports the guess and miss what contradicts it. Collecting evidence first, with each track carrying its own sources, keeps the diagnosis grounded in what the systems actually show rather than in the first plausible story."},{text:"Forming hypotheses first is slower, and the workflow optimizes each phase for speed",correct:!1,explanation:"The concern is soundness, not speed. Evidence-first prevents anchoring and cherry-picking; it is not chosen because it shaves time off the phase. A fast but hypothesis-anchored investigation is exactly what the ordering guards against."},{text:"Hypotheses cannot be written down until the incident is locked in step 1",correct:!1,explanation:"The lock (step 1) is about single ownership, separate from the evidence-then-hypothesis ordering in steps 2\u20133. You could technically write a hypothesis after locking; the point is that you should not, until evidence is collected."},{text:"Evidence collection must finish so the canary in step 14 has baseline metrics",correct:!1,explanation:"The canary verification is phase 4 and unrelated to why hypotheses come after evidence. Steps 2\u20133 order evidence before hypothesis to prevent anchoring during diagnosis, not to seed a later baseline."}]},{prompt:"In the review chain (IaC \u2192 security \u2192 FinOps \u2192 change-reviewer), the security stage objects to the plan while the others would pass it. What happens, and why is that the design?",options:[{text:"One dissent stops the line \u2014 the repair does not ship until the objection is resolved",correct:!0,explanation:"Correct. The chain is a JOIN, not a vote: every stage must clear the repair, so a single reasoned objection blocks it. That is what makes the review meaningful \u2014 a security concern cannot be out-voted by three stages that did not look at security."},{text:"The majority passes it, since three of four stages found no problem",correct:!1,explanation:"It is not a majority vote. A security objection is not overridden because three other stages, which were not evaluating security, had no concern. One dissent stops the line precisely so a real objection is not diluted by unrelated approvals."},{text:"The change-reviewer, as the last stage, overrides the earlier security objection",correct:!1,explanation:"No single stage overrides another; the reviewer performs a JOIN of all verdicts. A security block stands until resolved \u2014 the reviewer confirms every stage cleared, it does not have authority to wave a dissent through."},{text:"The plan ships with the objection recorded as a known risk to fix in the next release",correct:!1,explanation:"A blocking objection is not a note-and-ship item. The repair stops until the objection is addressed and the chain re-run; shipping over a live security dissent is exactly what the JOIN is designed to prevent."}]},{prompt:"The capstone grader scores seven rubric dimensions, each mapped to a phase. A run closes the incident but skipped the triage-lock. How does the grader treat it?",options:[{text:"It fails the triage-discipline dimension even though the metric recovered",correct:!0,explanation:"Correct. The rubric grades the reasoning and the process, not just the outcome \u2014 the same lesson M18 taught about a single run, now applied to the whole workflow. A recovered metric does not earn back a skipped lock, an un-reviewed apply, or a starter missing its change gate."},{text:"It passes overall, because closing the incident is the outcome that ultimately matters",correct:!1,explanation:"A closed incident does not paper over a skipped step. The grader scores each dimension independently; skipping the lock fails triage discipline regardless of the surface outcome, because the process is what is being tested."},{text:"It fails every dimension at once, since one skipped step invalidates the whole run",correct:!1,explanation:"The dimensions are scored independently, so a skipped lock fails triage discipline specifically \u2014 not all seven. A run can lose one dimension and still earn the others it actually performed correctly."},{text:"It defers scoring the run until a human reviewer confirms whether the skipped lock actually caused any harm downstream",correct:!1,explanation:"The grader does not wait on downstream harm. It scores the process against the rubric directly: the lock was skipped, so triage discipline fails now, independent of whether a race happened to occur this time."}]},{prompt:"The lesson stresses that what STAYS OUT of the starter matters as much as what goes in. Why is drawing that line the thing that makes the starter portable?",options:[{text:"Bundling Northstar's incidents and answer keys would make the starter a copy of one repo",correct:!0,explanation:"Correct. The line between reusable governance (role agents, hooks, contracts, the observer MCP) and one project's data (tickets, fixtures, answer keys) is what lets another team install and extend it. Ship the data and you have not packaged a layer \u2014 you have cloned Northstar."},{text:"Leaving data out makes the plugin smaller, so it downloads and installs faster",correct:!1,explanation:"Download size is incidental. The reason to exclude the tickets, fixtures, and answer keys is that they are project-specific \u2014 including them makes the starter unusable for anyone but Northstar, not merely larger."},{text:"Project data changes too often to keep a stable semver, so it is excluded for versioning hygiene",correct:!1,explanation:"The exclusion is about portability, not version churn. Northstar's incidents belong to Northstar; another team supplies its own. The governance schema is what is versioned and shipped, and the data is left out because it is not reusable."},{text:"The answer keys contain secrets that cannot be published in a shared plugin",correct:!1,explanation:"It is not primarily a secrets concern \u2014 the answer keys are graded against Northstar's specific incidents, so they are project data by nature. Even fully non-secret, they would not port, because each team writes its own keys for its own incidents."}]},{prompt:"Your three investigator tracks return three different root causes and the synthesizer reports verdict=disagreement. What has happened?",options:[{text:"Each track correctly found its own dimension's cause \u2014 INC-006 is compound",correct:!0,explanation:"Correct. The ticket lists five simultaneous failures with different causes. Three specialists confined to separate dimensions, each reading only its own evidence, will find different things because different things are wrong. The synthesizer says it plainly: a split is signal."},{text:"One investigator contaminated the others, so the conclusions diverged",correct:!1,explanation:"Contamination produces the opposite symptom. A track that read a peer's packet tends to agree with it, and declares that in derived_from \u2014 which the synthesizer rejects as theater at exit 4. Divergence is what independence looks like on a compound incident."},{text:"The run failed and the tracks should be re-run until they agree",correct:!1,explanation:"Re-running until three independent agents agree is manufacturing the consensus the course spends ten modules warning against. The disagreement is the finding; the work is resolving it, not deleting it."},{text:"The model tier was too low for the tracks to reach a reliable conclusion",correct:!1,explanation:"Tier is not the variable here, and all three tracks run on the same one precisely so it cannot be. Each conclusion was well-evidenced within its own dimension \u2014 they differ because the dimensions differ."}]},{prompt:"Phase 2 refuses your reconciliation: it records the platform-resource track as concluding 'retry-amplification', but that track concluded 'resource-exhaustion'. Why does the gate care?",options:[{text:"Restating what an investigator found is how a messy incident is made to look tidy",correct:!0,explanation:"Correct, and it is rarely experienced as dishonest \u2014 it feels like tidying. The gate reads your packets, so a reconciliation that quietly aligns everyone with your chosen primary is caught. Resolving a split means explaining it, not editing it."},{text:"The schema forbids repeating a root_cause value across two dimensions",correct:!1,explanation:"Nothing forbids two dimensions genuinely sharing a cause; that is what real corroboration looks like. What the gate rejects is recording a conclusion the track did not reach, whatever the value happens to be."},{text:"Only the primary dimension's root_cause is allowed to be filled in",correct:!1,explanation:"Every dimension that reported must be accounted for, including the ones you did not make primary \u2014 dropping the inconvenient track is a separate refusal the gate also issues."},{text:"The reconciliation must match fixtures/capstone/hypotheses.json",correct:!1,explanation:"The gates deliberately never read that fixture. It holds a worked answer and is ignored precisely so the capstone measures your evidence rather than the fixture's."}]},{prompt:"Part I launches each track as `claude -p --agent <role>` in its own process rather than asking one session to dispatch subagents. Which statements about that choice are correct? (Select all that apply.)",options:[{text:"None of these roles carries a Task tool, so a dispatch request had nowhere to go",correct:!0,explanation:"Correct. The earlier version asked a general session to 'dispatch four subagents' with no mechanism behind the request \u2014 the same silent non-event Module 17 measured, where the model describes a fan-out it cannot perform and reports success."},{text:"Separate processes make 'do not read the other tracks' structurally true",correct:!0,explanation:"Correct, and this is the real gain. Independence stops depending on the model honouring an instruction and becomes a property of how the work was run \u2014 separate processes cannot see each other's context."},{text:"Running them concurrently buys wall-clock without changing the cost",correct:!0,explanation:"Correct. Measured here: 149 seconds in parallel against 334 sequential, for the same spend. You pay for the same three investigations either way and get the answer sooner."},{text:"It guarantees the three tracks will reach independent conclusions",correct:!1,explanation:"It removes the easiest way to contaminate them, not every way. A track can still anchor on the incident ticket's own framing, which is why derived_from is declared and phase 5 counts it."},{text:"It is a workaround that a Task-capable role would do better",correct:!1,explanation:"Backwards. A Task-based fan-out shares one context and makes isolation a matter of instruction-following; separate processes make it structural. Here the simpler mechanism is the stronger one."}],multiSelect:!0}]})]})}function p(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(d,{...e})}):d(e)}},7517(e,t,o){o.d(t,{A:()=>s});var a=o(4848),n=o(6540);function i({q:e,state:t,onToggle:o}){return(0,a.jsxs)("div",{className:"question_QpiT",children:[(0,a.jsx)("p",{className:"prompt_TqRJ",children:e.prompt}),e.multiSelect&&(0,a.jsx)("p",{className:"hint_e_F7",children:"(select all that apply)"}),(0,a.jsx)("ul",{className:"options_X9pq",children:e.options.map((e,n)=>{let i=t.selected.has(n),s="option_qGol";return t.checked?e.correct?s+=" correct_LYA5":i&&(s+=" incorrect_kRFc"):i&&(s+=" chosen_H3WG"),(0,a.jsxs)("li",{children:[(0,a.jsxs)("button",{type:"button",className:s,disabled:t.checked,onClick:()=>o(n),children:[(0,a.jsx)("span",{className:"marker_vN_w",children:i?"\u25CF":"\u25CB"})," ",e.text]}),t.checked&&(i||e.correct)&&e.explanation&&(0,a.jsx)("p",{className:"explanation_HBZ0",children:e.explanation})]},n)})})]})}function s({questions:e}){let[t,o]=(0,n.useState)(e.map(()=>({selected:new Set,checked:!1}))),r=t.every(e=>e.checked),c=t.filter((t,o)=>{var a,n;let i;return a=e[o],n=t.selected,i=a.options.map((e,t)=>e.correct?t:-1).filter(e=>e>=0),a.multiSelect?n.size===i.length&&[...n].every(e=>a.options[e].correct):1===n.size&&i.includes([...n][0])}).length;return(0,a.jsxs)("div",{className:"quiz_I014",children:[e.map((n,s)=>(0,a.jsx)(i,{q:n,state:t[s],onToggle:t=>o(o=>o.map((o,a)=>{if(a!==s)return o;let n=new Set(o.selected);return e[s].multiSelect?n.has(t)?n.delete(t):n.add(t):(n.clear(),n.add(t)),{...o,selected:n}}))},s)),(0,a.jsxs)("div",{className:"actions_XUwt",children:[(0,a.jsx)("button",{type:"button",className:"check_wZ2j",onClick:()=>o(e=>e.map(e=>({...e,checked:!0}))),children:"Check answers"}),(0,a.jsx)("button",{type:"button",className:"resetBtn_JHSa",onClick:()=>o(e.map(()=>({selected:new Set,checked:!1}))),children:"Reset"}),r&&(0,a.jsxs)("span",{className:"score_AN7p",children:["Score: ",c," / ",e.length]})]})]})}},8453(e,t,o){o.d(t,{R:()=>s,x:()=>r});var a=o(6540);let n={},i=a.createContext(n);function s(e){let t=a.useContext(i);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:s(e.components),a.createElement(i.Provider,{value:t},e.children)}}}]);